INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$6d247c13$SATQ$, $SATQ$564abc36-ce43-4c8b-a08b-694a067c2f1d$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>The Boston Saloon was one of the most popular African American&ndash;owned establishments in nineteenth-century Nevada. <span aria-hidden="true">______</span><span class="sr-only">blank</span> by businessman William A.G. Brown, the saloon was known to offer elegant accommodations and an inclusive environment.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"30f1eca4-bde8-4595-9f73-1562877ebab0","content":"<p>Created</p>"},{"id":"fb4a22d7-ebb2-46aa-a6a0-47cc93f45915","content":"<p>Creates</p>"},{"id":"ac1f3e45-3523-4a05-aef1-394dff24dfed","content":"<p>Creating</p>"},{"id":"5e7f19a6-aede-4d61-8095-96829f6fe499","content":"<p>Create</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["30f1eca4-bde8-4595-9f73-1562877ebab0"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite past participle "created" is correctly used to form a supplementary element that modifies the noun phrase "the saloon," identifying who established the Boston Saloon.</p><p>Choice B is incorrect because it results in an ungrammatical sentence. The finite present tense verb "creates" can&rsquo;t be used in this way to form a supplementary element to modify the noun phrase "the saloon." Choice C is incorrect because it results in an ungrammatical sentence. The nonfinite present participle "creating" can&rsquo;t be used in this way to form a supplementary element to modify the noun phrase "the saloon." Choice D is incorrect because it results in an ungrammatical sentence. The finite present tense verb "create" can&rsquo;t be used in this way to form a supplementary element to modify the noun phrase "the saloon."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"6d247c13","external_id":"564abc36-ce43-4c8b-a08b-694a067c2f1d","vaultid":null,"uId":"efd04f10-27e8-4a7a-a895-e2d91e5e140f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>The Boston Saloon was one of the most popular African American&ndash;owned establishments in nineteenth-century Nevada. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> by businessman William A.G. Brown, the saloon was known to offer elegant accommodations and an inclusive environment.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"30f1eca4-bde8-4595-9f73-1562877ebab0","content":"<p>Created</p>"},{"id":"fb4a22d7-ebb2-46aa-a6a0-47cc93f45915","content":"<p>Creates</p>"},{"id":"ac1f3e45-3523-4a05-aef1-394dff24dfed","content":"<p>Creating</p>"},{"id":"5e7f19a6-aede-4d61-8095-96829f6fe499","content":"<p>Create</p>"}],"keys":["30f1eca4-bde8-4595-9f73-1562877ebab0"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite past participle \"created\" is correctly used to form a supplementary element that modifies the noun phrase \"the saloon,\" identifying who established the Boston Saloon.</p><p>Choice B is incorrect because it results in an ungrammatical sentence. The finite present tense verb \"creates\" can&rsquo;t be used in this way to form a supplementary element to modify the noun phrase \"the saloon.\" Choice C is incorrect because it results in an ungrammatical sentence. The nonfinite present participle \"creating\" can&rsquo;t be used in this way to form a supplementary element to modify the noun phrase \"the saloon.\" Choice D is incorrect because it results in an ungrammatical sentence. The finite present tense verb \"create\" can&rsquo;t be used in this way to form a supplementary element to modify the noun phrase \"the saloon.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323047,"updateDate":1730147323047}$SATQ$::jsonb, 1730147323047, 1730147323047),
    ($SATQ$6d4b2e1e$SATQ$, $SATQ$195e23f6-ec4e-4d53-b072-1e61cd17d277$SATQ$::uuid, $SATQ$c39ba629-39f0-49ff-8d9a-b53879770057$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>The 1977 play <em>And the Soul Shall Dance</em> depicts two Japanese American farming families in Depression-era Southern California. Critics have noted the way pioneering <span aria-hidden="true">______</span><span class="sr-only">blank</span> compares the experiences of <span lang="ja"><em>issei</em></span> (Japanese nationals who emigrated to America) and <span lang="ja"><em>nisei</em></span> (their American-born children).</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"6b145e50-9243-418a-b2c5-893fc420b529","content":"<p>playwright, Wakako Yamauchi,</p>"},{"id":"c72e04f0-ee90-4ca4-901c-11bb1cb1097c","content":"<p>playwright, Wakako Yamauchi</p>"},{"id":"306c1c93-41f8-4d54-b907-95d786813713","content":"<p>playwright Wakako Yamauchi,</p>"},{"id":"d801eb00-c794-4397-8201-89cee2ace6c1","content":"<p>playwright Wakako Yamauchi</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["d801eb00-c794-4397-8201-89cee2ace6c1"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is the use of punctuation between titles and proper nouns. No punctuation is needed to set off the proper noun "Wakako Yamauchi" from the title that describes Yamauchi, "pioneering playwright." Because "Wakako Yamauchi" is essential information identifying the "pioneering playwright," no punctuation is necessary.</p><p>Choice A is incorrect because no punctuation is needed before or after the proper noun "Wakako Yamauchi." Setting the playwright&rsquo;s name off with commas suggests that it could be removed without affecting the coherence of the sentence, which isn&rsquo;t the case. Choice B is incorrect because no punctuation is needed between the title "pioneering playwright" and the proper noun "Wakako Yamauchi." Choice C is incorrect because no punctuation is needed between the proper noun "Wakako Yamauchi" and the verb "compares."</p>$SATQ$, false, 0, $SATQ$OSP-KA-BOU-H005$SATQ$, $SATQ$$SATQ$, $SATQ$7776c7b5-bd64-4781-abee-29e0e70f698f$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"6d4b2e1e","external_id":"195e23f6-ec4e-4d53-b072-1e61cd17d277","vaultid":"c39ba629-39f0-49ff-8d9a-b53879770057","uId":"d4978655-6d1e-441a-8fa7-002457a86b98","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>The 1977 play <em>And the Soul Shall Dance</em> depicts two Japanese American farming families in Depression-era Southern California. Critics have noted the way pioneering <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> compares the experiences of <span lang=\"ja\"><em>issei</em></span> (Japanese nationals who emigrated to America) and <span lang=\"ja\"><em>nisei</em></span> (their American-born children).</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"6b145e50-9243-418a-b2c5-893fc420b529","content":"<p>playwright, Wakako Yamauchi,</p>"},{"id":"c72e04f0-ee90-4ca4-901c-11bb1cb1097c","content":"<p>playwright, Wakako Yamauchi</p>"},{"id":"306c1c93-41f8-4d54-b907-95d786813713","content":"<p>playwright Wakako Yamauchi,</p>"},{"id":"d801eb00-c794-4397-8201-89cee2ace6c1","content":"<p>playwright Wakako Yamauchi</p>"}],"keys":["d801eb00-c794-4397-8201-89cee2ace6c1"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is the use of punctuation between titles and proper nouns. No punctuation is needed to set off the proper noun \"Wakako Yamauchi\" from the title that describes Yamauchi, \"pioneering playwright.\" Because \"Wakako Yamauchi\" is essential information identifying the \"pioneering playwright,\" no punctuation is necessary.</p><p>Choice A is incorrect because no punctuation is needed before or after the proper noun \"Wakako Yamauchi.\" Setting the playwright&rsquo;s name off with commas suggests that it could be removed without affecting the coherence of the sentence, which isn&rsquo;t the case. Choice B is incorrect because no punctuation is needed between the title \"pioneering playwright\" and the proper noun \"Wakako Yamauchi.\" Choice C is incorrect because no punctuation is needed between the proper noun \"Wakako Yamauchi\" and the verb \"compares.\"</p>","parenttemplatename":"OSP-KA-BOU-H005","parenttemplateid":"","templateclusterid":"7776c7b5-bd64-4781-abee-29e0e70f698f","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959358,"updateDate":1691007959358}$SATQ$::jsonb, 1691007959358, 1691007959358),
    ($SATQ$6df020e6$SATQ$, $SATQ$6536f9e4-0474-46f2-9804-9baa25c5bea6$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>A study showed that a solar park caused nearby land to cool, though the ecological impact of this temperature decrease isn&rsquo;t yet known. Before the park&rsquo;s construction, the surface temperature 30 meters outside of the park boundary was 0.1&deg;C cooler than that of a control <span aria-hidden="true">______</span><span class="sr-only">blank</span> construction, the temperature 30 meters outside of the boundary was 1.7&deg;C cooler than that of the control area.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"b6701b9d-2cd0-474b-bf5d-5cbbbf7b6238","content":"<p>area after</p>"},{"id":"d984379b-23ae-47e4-a347-bbe5307ac611","content":"<p>area after,</p>"},{"id":"c38efdf7-dec4-457e-ba64-23cfcfb83d4f","content":"<p>area. After</p>"},{"id":"27a5d37b-fc30-49f9-8e45-d7dfe0c44592","content":"<p>area, after</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["c38efdf7-dec4-457e-ba64-23cfcfb83d4f"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used to correctly mark the boundary between one sentence ("Before...area") and another ("After...area"). The phrase "After construction" modifies the next sentence to indicate that the temperature was cooler after construction.</p><p>Choice A is incorrect because it results in a run-on sentence that fuses the two sentences ("Before...area" and "after...area") without punctuation and/or a conjunction. Choice B is incorrect because it results in a run-on sentence that connects the two sentences ("Before...area" and "after...area") without punctuation and/or a conjunction. Additionally, no punctuation is needed between "after" and "construction." Choice D is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between the two sentences ("Before...area" and "after...area").</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"6df020e6","external_id":"6536f9e4-0474-46f2-9804-9baa25c5bea6","vaultid":null,"uId":"70ef2989-5dda-416e-8533-66186c6c79d4","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>A study showed that a solar park caused nearby land to cool, though the ecological impact of this temperature decrease isn&rsquo;t yet known. Before the park&rsquo;s construction, the surface temperature 30 meters outside of the park boundary was 0.1&deg;C cooler than that of a control <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> construction, the temperature 30 meters outside of the boundary was 1.7&deg;C cooler than that of the control area.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"b6701b9d-2cd0-474b-bf5d-5cbbbf7b6238","content":"<p>area after</p>"},{"id":"d984379b-23ae-47e4-a347-bbe5307ac611","content":"<p>area after,</p>"},{"id":"c38efdf7-dec4-457e-ba64-23cfcfb83d4f","content":"<p>area. After</p>"},{"id":"27a5d37b-fc30-49f9-8e45-d7dfe0c44592","content":"<p>area, after</p>"}],"keys":["c38efdf7-dec4-457e-ba64-23cfcfb83d4f"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used to correctly mark the boundary between one sentence (\"Before...area\") and another (\"After...area\"). The phrase \"After construction\" modifies the next sentence to indicate that the temperature was cooler after construction.</p><p>Choice A is incorrect because it results in a run-on sentence that fuses the two sentences (\"Before...area\" and \"after...area\") without punctuation and/or a conjunction. Choice B is incorrect because it results in a run-on sentence that connects the two sentences (\"Before...area\" and \"after...area\") without punctuation and/or a conjunction. Additionally, no punctuation is needed between \"after\" and \"construction.\" Choice D is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between the two sentences (\"Before...area\" and \"after...area\").</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323047,"updateDate":1730147323047}$SATQ$::jsonb, 1730147323047, 1730147323047),
    ($SATQ$6e071432$SATQ$, $SATQ$27dcef67-fa3b-4d14-8bc9-703bcc36b1b1$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>In 1986, conceptual artist Sophie Calle asked twenty-three people, all of whom had been born without sight, to describe &ldquo;their image of beauty&rdquo; in rich detail. Calle paired excerpts of these conversations with photographs&mdash;both of interviewees and the items they <span aria-hidden="true">______</span><span class="sr-only">blank</span> to powerful effect in her exhibition <em>The Blind</em>.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"9f21b082-5dee-4596-83d8-5edfb8a17baf","content":"<p>described, from hair to grass to sculptures</p>"},{"id":"8f0d337a-66ce-4f8a-bf4b-fc3b53ace3e2","content":"<p>described, from hair to grass to sculptures&mdash;</p>"},{"id":"3db22bab-764c-4822-90e9-10ae2374073d","content":"<p>described&mdash;from hair to grass to sculptures,</p>"},{"id":"fcf23723-b4e3-442c-99d2-736f1c6e0392","content":"<p>described: from hair to grass to sculptures</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["8f0d337a-66ce-4f8a-bf4b-fc3b53ace3e2"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is the punctuation of supplementary elements within a sentence. The comma after "described" separates the first supplementary element ("both of interviewees and the items they described") from the second supplementary element ("from hair to grass to sculptures"). Furthermore, the dash after "sculptures" pairs with the dash after "photographs" to separate these two supplementary elements from the rest of the sentence. The pair of dashes, which operate at a higher organizing level than the comma, indicates that the elements between the dashes function together&mdash;in this case, the second supplement ("from&hellip;sculptures") describes the range of items mentioned in the first supplement&mdash;and could be removed without affecting the grammatical coherence of the sentence.</p><p>Choice A is incorrect because it fails to appropriately punctuate the supplementary elements in the sentence. A dash is needed after "sculptures" to separate the supplementary elements ("both&hellip;sculptures") from the rest of the sentence. Choice C is incorrect because it fails to appropriately punctuate the supplementary elements in the sentence. The two supplementary elements "both&hellip;described" and "from&hellip;sculptures" function together to describe the photographs, and placing a dash between them would make this relationship less clear, suggesting that the supplement "both...described" is a standalone element that could be removed without affecting the grammatical coherence of the sentence, which isn&rsquo;t the case. Choice D is incorrect because it fails to appropriately punctuate the supplementary elements in the sentence. A colon isn&rsquo;t conventionally used in this way to separate a supplementary element ("from hair to grass to sculptures") from the noun phrase it is modifying ("items they described"). Additionally, a dash is needed after "sculptures" to separate the supplementary elements ("both&hellip;sculptures") from the rest of the sentence.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"6e071432","external_id":"27dcef67-fa3b-4d14-8bc9-703bcc36b1b1","vaultid":null,"uId":"3390f795-8252-4d80-bbd1-e7b0a7e5a63a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>In 1986, conceptual artist Sophie Calle asked twenty-three people, all of whom had been born without sight, to describe &ldquo;their image of beauty&rdquo; in rich detail. Calle paired excerpts of these conversations with photographs&mdash;both of interviewees and the items they <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> to powerful effect in her exhibition <em>The Blind</em>.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"9f21b082-5dee-4596-83d8-5edfb8a17baf","content":"<p>described, from hair to grass to sculptures</p>"},{"id":"8f0d337a-66ce-4f8a-bf4b-fc3b53ace3e2","content":"<p>described, from hair to grass to sculptures&mdash;</p>"},{"id":"3db22bab-764c-4822-90e9-10ae2374073d","content":"<p>described&mdash;from hair to grass to sculptures,</p>"},{"id":"fcf23723-b4e3-442c-99d2-736f1c6e0392","content":"<p>described: from hair to grass to sculptures</p>"}],"keys":["8f0d337a-66ce-4f8a-bf4b-fc3b53ace3e2"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is the punctuation of supplementary elements within a sentence. The comma after \"described\" separates the first supplementary element (\"both of interviewees and the items they described\") from the second supplementary element (\"from hair to grass to sculptures\"). Furthermore, the dash after \"sculptures\" pairs with the dash after \"photographs\" to separate these two supplementary elements from the rest of the sentence. The pair of dashes, which operate at a higher organizing level than the comma, indicates that the elements between the dashes function together&mdash;in this case, the second supplement (\"from&hellip;sculptures\") describes the range of items mentioned in the first supplement&mdash;and could be removed without affecting the grammatical coherence of the sentence.</p><p>Choice A is incorrect because it fails to appropriately punctuate the supplementary elements in the sentence. A dash is needed after \"sculptures\" to separate the supplementary elements (\"both&hellip;sculptures\") from the rest of the sentence. Choice C is incorrect because it fails to appropriately punctuate the supplementary elements in the sentence. The two supplementary elements \"both&hellip;described\" and \"from&hellip;sculptures\" function together to describe the photographs, and placing a dash between them would make this relationship less clear, suggesting that the supplement \"both...described\" is a standalone element that could be removed without affecting the grammatical coherence of the sentence, which isn&rsquo;t the case. Choice D is incorrect because it fails to appropriately punctuate the supplementary elements in the sentence. A colon isn&rsquo;t conventionally used in this way to separate a supplementary element (\"from hair to grass to sculptures\") from the noun phrase it is modifying (\"items they described\"). Additionally, a dash is needed after \"sculptures\" to separate the supplementary elements (\"both&hellip;sculptures\") from the rest of the sentence.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323049,"updateDate":1730147323049}$SATQ$::jsonb, 1730147323049, 1730147323049),
    ($SATQ$6e193b19$SATQ$, $SATQ$6130db83-ad00-4590-b9b5-27ba06a70f9a$SATQ$::uuid, $SATQ$caef9863-b370-4999-856c-a29b6bdaf4a2$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Professional American football player Fred Cox invented one of the world&rsquo;s most popular toys. In the 1970s, he came up with the idea for the Nerf football, which <span aria-hidden="true">______</span><span class="sr-only">blank</span> of the harder and heavier regulation football.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"d625e29b-de17-4524-b09e-5248ce2d0e93","content":"<p>were a smaller, foam version</p>"},{"id":"d90a6579-7923-46e4-8c0d-2523ddd4ed0a","content":"<p>are smaller, foam versions</p>"},{"id":"3d8b6d54-a0e7-426d-9d70-a076c78448a0","content":"<p>were smaller, foam versions</p>"},{"id":"205f6061-9626-4393-871e-a2b7a6d9ec07","content":"<p>is a smaller, foam version</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["205f6061-9626-4393-871e-a2b7a6d9ec07"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is subject-verb agreement and agreement between nouns. The singular verb &ldquo;is&rdquo; and the singular noun &ldquo;version&rdquo; both agree in number with the relative pronoun &ldquo;which.&rdquo; In this context, &ldquo;which&rdquo; functions as a singular subject because it refers to the singular noun &ldquo;the Nerf football.&rdquo; </p><p>Choice A is incorrect because the plural verb &ldquo;were&rdquo; doesn&rsquo;t agree in number with the singular noun phrase &ldquo;the Nerf football&rdquo; that it&rsquo;s modifying. Choice B is incorrect because the plural verb &ldquo;are&rdquo; and the plural noun &ldquo;versions&rdquo; don&rsquo;t agree in number with the singular noun phrase &ldquo;the Nerf football&rdquo; that they&rsquo;re modifying. Choice C is incorrect because the plural verb &ldquo;were&rdquo; and the plural noun &ldquo;versions&rdquo; don&rsquo;t agree in number with the singular noun phrase &ldquo;the Nerf football&rdquo; that they&rsquo;re modifying. </p>$SATQ$, false, 0, $SATQ$OSP-699-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$fa7db512-760f-476f-bccf-951038e955ca$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"6e193b19","external_id":"6130db83-ad00-4590-b9b5-27ba06a70f9a","vaultid":"caef9863-b370-4999-856c-a29b6bdaf4a2","uId":"1aaf8ab9-60cf-45ad-9ff3-3599f7a33f36","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Professional American football player Fred Cox invented one of the world&rsquo;s most popular toys. In the 1970s, he came up with the idea for the Nerf football, which <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> of the harder and heavier regulation football.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"d625e29b-de17-4524-b09e-5248ce2d0e93","content":"<p>were a smaller, foam version</p>"},{"id":"d90a6579-7923-46e4-8c0d-2523ddd4ed0a","content":"<p>are smaller, foam versions</p>"},{"id":"3d8b6d54-a0e7-426d-9d70-a076c78448a0","content":"<p>were smaller, foam versions</p>"},{"id":"205f6061-9626-4393-871e-a2b7a6d9ec07","content":"<p>is a smaller, foam version</p>"}],"keys":["205f6061-9626-4393-871e-a2b7a6d9ec07"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is subject-verb agreement and agreement between nouns. The singular verb &ldquo;is&rdquo; and the singular noun &ldquo;version&rdquo; both agree in number with the relative pronoun &ldquo;which.&rdquo; In this context, &ldquo;which&rdquo; functions as a singular subject because it refers to the singular noun &ldquo;the Nerf football.&rdquo; </p><p>Choice A is incorrect because the plural verb &ldquo;were&rdquo; doesn&rsquo;t agree in number with the singular noun phrase &ldquo;the Nerf football&rdquo; that it&rsquo;s modifying. Choice B is incorrect because the plural verb &ldquo;are&rdquo; and the plural noun &ldquo;versions&rdquo; don&rsquo;t agree in number with the singular noun phrase &ldquo;the Nerf football&rdquo; that they&rsquo;re modifying. Choice C is incorrect because the plural verb &ldquo;were&rdquo; and the plural noun &ldquo;versions&rdquo; don&rsquo;t agree in number with the singular noun phrase &ldquo;the Nerf football&rdquo; that they&rsquo;re modifying. </p>","parenttemplatename":"OSP-699-SEC","parenttemplateid":"","templateclusterid":"fa7db512-760f-476f-bccf-951038e955ca","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959347,"updateDate":1691007959347}$SATQ$::jsonb, 1691007959347, 1691007959347),
    ($SATQ$6e5bf3a8$SATQ$, $SATQ$0765ff91-480b-4dbc-9180-944329c2b26d$SATQ$::uuid, $SATQ$f8b29d31-679d-4e38-8f35-326b4a9878b1$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Even though bats prefer very sweet nectar, the plants that attract them have evolved to produce nectar that is only moderately sweet. A recent study <span aria-hidden="true">______</span><span class="sr-only">blank</span> why: making sugar is energy-intensive, and it is more advantageous for plants to make a large amount of low-sugar nectar than a small amount of high-sugar nectar.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"4f6b7b1a-7695-49b6-8fe0-78d3e20d51cd","content":"<p>explains</p>"},{"id":"52e62e6c-dd06-401c-8427-385472b0ebbf","content":"<p>explaining</p>"},{"id":"b432d356-d63c-4fcc-937c-303af25ebccd","content":"<p>having explained</p>"},{"id":"92caecd4-0d99-42b1-91d4-9ed57879c36a","content":"<p>to explain</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["4f6b7b1a-7695-49b6-8fe0-78d3e20d51cd"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of finite and nonfinite verb forms within a sentence. A main clause requires a finite verb to perform the action of the subject (in this case, &ldquo;a recent study&rdquo;), and this choice supplies the finite present tense verb &ldquo;explains&rdquo; to indicate that the study explains why plants that attract bats have evolved to produce moderately sweet nectar.&nbsp;</p><p>Choice B is incorrect because the nonfinite participle &ldquo;explaining&rdquo; doesn&rsquo;t supply the main clause with a finite verb.&nbsp;Choice C is incorrect because the nonfinite participle &ldquo;having explained&rdquo; doesn&rsquo;t supply the main clause with a finite verb. Choice D is incorrect because the nonfinite to-infinitive &ldquo;to explain&rdquo; doesn&rsquo;t supply the main clause with a finite verb. </p>$SATQ$, false, 0, $SATQ$OSP-708-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$d85195fd-16c1-4631-b5bc-af568e6e6e28$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"6e5bf3a8","external_id":"0765ff91-480b-4dbc-9180-944329c2b26d","vaultid":"f8b29d31-679d-4e38-8f35-326b4a9878b1","uId":"9079f080-53be-4dac-ae49-621e7cfcf2bc","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Even though bats prefer very sweet nectar, the plants that attract them have evolved to produce nectar that is only moderately sweet. A recent study <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> why: making sugar is energy-intensive, and it is more advantageous for plants to make a large amount of low-sugar nectar than a small amount of high-sugar nectar.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"4f6b7b1a-7695-49b6-8fe0-78d3e20d51cd","content":"<p>explains</p>"},{"id":"52e62e6c-dd06-401c-8427-385472b0ebbf","content":"<p>explaining</p>"},{"id":"b432d356-d63c-4fcc-937c-303af25ebccd","content":"<p>having explained</p>"},{"id":"92caecd4-0d99-42b1-91d4-9ed57879c36a","content":"<p>to explain</p>"}],"keys":["4f6b7b1a-7695-49b6-8fe0-78d3e20d51cd"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of finite and nonfinite verb forms within a sentence. A main clause requires a finite verb to perform the action of the subject (in this case, &ldquo;a recent study&rdquo;), and this choice supplies the finite present tense verb &ldquo;explains&rdquo; to indicate that the study explains why plants that attract bats have evolved to produce moderately sweet nectar.&nbsp;</p><p>Choice B is incorrect because the nonfinite participle &ldquo;explaining&rdquo; doesn&rsquo;t supply the main clause with a finite verb.&nbsp;Choice C is incorrect because the nonfinite participle &ldquo;having explained&rdquo; doesn&rsquo;t supply the main clause with a finite verb. Choice D is incorrect because the nonfinite to-infinitive &ldquo;to explain&rdquo; doesn&rsquo;t supply the main clause with a finite verb. </p>","parenttemplatename":"OSP-708-SEC","parenttemplateid":"","templateclusterid":"d85195fd-16c1-4631-b5bc-af568e6e6e28","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959347,"updateDate":1691007959347}$SATQ$::jsonb, 1691007959347, 1691007959347),
    ($SATQ$6ea8c23f$SATQ$, $SATQ$42ca5120-4c07-4e04-98e7-e2990f2fdebd$SATQ$::uuid, $SATQ$f55c207a-635e-4f99-9f33-bdf51fc109d2$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>In 2018, a team of researchers led by Dr. Caitlin Whalen compiled every available measurement of ocean mixing rates from the past two decades. With this novel data set, the team was able to determine how current-driven mixing varies across <span aria-hidden="true">______</span><span class="sr-only">blank</span> and what impact it has on the distribution of heat and nutrients in the ocean.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"350efe64-ae0b-4050-be32-749ac25c87c9","content":"<p>regions,</p>"},{"id":"93e8b565-0bb2-4fe6-85e6-4855154b61ec","content":"<p>regions:</p>"},{"id":"e2af52aa-7028-43eb-b4d2-fea5df9a68a4","content":"<p>regions;</p>"},{"id":"fbbe739f-9bc6-4e4a-8e0e-800d957409cb","content":"<p>regions</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["fbbe739f-9bc6-4e4a-8e0e-800d957409cb"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is punctuation between coordinates in a sentence. The two elements "how&hellip;regions" and "what&hellip;ocean" work together as coordinates to complete the description of what the team was able to determine. Because there are only two coordinates in this case (as opposed to a series of three or more), no punctuation is needed between them.</p><p>Choice A is incorrect because no punctuation is needed between the coordinates "how&hellip;regions" and "what&hellip;ocean." Choice B is incorrect because no punctuation is needed between the coordinates "how&hellip;regions" and "what&hellip;ocean." Choice C is incorrect because no punctuation is needed between the coordinates "how&hellip;regions" and "what&hellip;ocean."</p>$SATQ$, false, 0, $SATQ$OSP-673-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$e23b3a6b-5c8d-48e0-8f66-272b7e486184$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"6ea8c23f","external_id":"42ca5120-4c07-4e04-98e7-e2990f2fdebd","vaultid":"f55c207a-635e-4f99-9f33-bdf51fc109d2","uId":"347ba3c3-2481-47a4-b84c-b8c3372835a8","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>In 2018, a team of researchers led by Dr. Caitlin Whalen compiled every available measurement of ocean mixing rates from the past two decades. With this novel data set, the team was able to determine how current-driven mixing varies across <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> and what impact it has on the distribution of heat and nutrients in the ocean.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"350efe64-ae0b-4050-be32-749ac25c87c9","content":"<p>regions,</p>"},{"id":"93e8b565-0bb2-4fe6-85e6-4855154b61ec","content":"<p>regions:</p>"},{"id":"e2af52aa-7028-43eb-b4d2-fea5df9a68a4","content":"<p>regions;</p>"},{"id":"fbbe739f-9bc6-4e4a-8e0e-800d957409cb","content":"<p>regions</p>"}],"keys":["fbbe739f-9bc6-4e4a-8e0e-800d957409cb"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is punctuation between coordinates in a sentence. The two elements \"how&hellip;regions\" and \"what&hellip;ocean\" work together as coordinates to complete the description of what the team was able to determine. Because there are only two coordinates in this case (as opposed to a series of three or more), no punctuation is needed between them.</p><p>Choice A is incorrect because no punctuation is needed between the coordinates \"how&hellip;regions\" and \"what&hellip;ocean.\" Choice B is incorrect because no punctuation is needed between the coordinates \"how&hellip;regions\" and \"what&hellip;ocean.\" Choice C is incorrect because no punctuation is needed between the coordinates \"how&hellip;regions\" and \"what&hellip;ocean.\"</p>","parenttemplatename":"OSP-673-SEC","parenttemplateid":"","templateclusterid":"e23b3a6b-5c8d-48e0-8f66-272b7e486184","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959346,"updateDate":1691007959346}$SATQ$::jsonb, 1691007959346, 1691007959346),
    ($SATQ$6f08641e$SATQ$, $SATQ$c0873d88-f061-492d-a514-e5e581fab367$SATQ$::uuid, $SATQ$98ff772d-1268-4f30-b3c8-a7a66f25ebdf$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>On April 5, 1977, Kitty Cone and 150 other disability rights activists entered a San Francisco federal building. After pleading for years&mdash;to no effect&mdash;for the passage of key antidiscrimination legislation, <span aria-hidden="true">______</span><span class="sr-only">blank</span> until their demands were addressed. Finally, on April 28, the legislation was signed.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"d4334c54-ec35-47d2-8d04-aa69ddfe74d7","content":"<p>pressure on lawmakers increased when the activists staged a sit-in protest</p>"},{"id":"fb772430-b70a-427f-b606-73c04ec866c8","content":"<p>a sit-in protest staged by the activists increased pressure on lawmakers</p>"},{"id":"27690ed2-ad1d-4f95-8ca4-05f2c518c277","content":"<p>lawmakers came under increased pressure when the activists staged a sit-in protest</p>"},{"id":"a850b154-7f56-4e0a-a4c2-fb2a943880f1","content":"<p>the activists increased pressure on lawmakers by staging a sit-in protest</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["a850b154-7f56-4e0a-a4c2-fb2a943880f1"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is subject-modifier placement. This choice makes the noun phrase &ldquo;the activists&rdquo; the subject of the sentence and places it immediately after the modifying phrase &ldquo;after...legislation.&rdquo; In doing so, this choice clearly establishes that the activists&mdash;and not another noun in the sentence&mdash;were pleading for the passage of antidiscrimination legislation. </p><p>Choice A is incorrect because it results in a dangling modifier. The placement of the noun phrase &ldquo;pressure on lawmakers&rdquo; immediately after the modifying phrase illogically suggests that the &ldquo;pressure&rdquo; was pleading for the passage of antidiscrimination legislation. Choice B is incorrect because it results in a dangling modifier. The placement of the noun phrase &ldquo;a sit-in protest&rdquo; immediately after the modifying phrase illogically suggests that the &ldquo;protest&rdquo; was pleading for the passage of antidiscrimination legislation. Choice C is incorrect because it results in a dangling modifier. The placement of the noun phrase &ldquo;lawmakers&rdquo; immediately after the modifying phrase suggests that &ldquo;lawmakers&rdquo; were pleading for the passage of antidiscrimination legislation. While it&rsquo;s possible for lawmakers to plead for the passage of legislation, the context strongly suggests that it&rsquo;s the activists who pleaded for years for the passage of antidiscrimination legislation. </p>$SATQ$, false, 0, $SATQ$OSP-771-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$af358553-2b60-4afb-b29d-ca851ae54609$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"6f08641e","external_id":"c0873d88-f061-492d-a514-e5e581fab367","vaultid":"98ff772d-1268-4f30-b3c8-a7a66f25ebdf","uId":"04381bd9-2a6d-449b-a83e-f3e8a1a45e0e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>On April 5, 1977, Kitty Cone and 150 other disability rights activists entered a San Francisco federal building. After pleading for years&mdash;to no effect&mdash;for the passage of key antidiscrimination legislation, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> until their demands were addressed. Finally, on April 28, the legislation was signed.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"d4334c54-ec35-47d2-8d04-aa69ddfe74d7","content":"<p>pressure on lawmakers increased when the activists staged a sit-in protest</p>"},{"id":"fb772430-b70a-427f-b606-73c04ec866c8","content":"<p>a sit-in protest staged by the activists increased pressure on lawmakers</p>"},{"id":"27690ed2-ad1d-4f95-8ca4-05f2c518c277","content":"<p>lawmakers came under increased pressure when the activists staged a sit-in protest</p>"},{"id":"a850b154-7f56-4e0a-a4c2-fb2a943880f1","content":"<p>the activists increased pressure on lawmakers by staging a sit-in protest</p>"}],"keys":["a850b154-7f56-4e0a-a4c2-fb2a943880f1"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is subject-modifier placement. This choice makes the noun phrase &ldquo;the activists&rdquo; the subject of the sentence and places it immediately after the modifying phrase &ldquo;after...legislation.&rdquo; In doing so, this choice clearly establishes that the activists&mdash;and not another noun in the sentence&mdash;were pleading for the passage of antidiscrimination legislation. </p><p>Choice A is incorrect because it results in a dangling modifier. The placement of the noun phrase &ldquo;pressure on lawmakers&rdquo; immediately after the modifying phrase illogically suggests that the &ldquo;pressure&rdquo; was pleading for the passage of antidiscrimination legislation. Choice B is incorrect because it results in a dangling modifier. The placement of the noun phrase &ldquo;a sit-in protest&rdquo; immediately after the modifying phrase illogically suggests that the &ldquo;protest&rdquo; was pleading for the passage of antidiscrimination legislation. Choice C is incorrect because it results in a dangling modifier. The placement of the noun phrase &ldquo;lawmakers&rdquo; immediately after the modifying phrase suggests that &ldquo;lawmakers&rdquo; were pleading for the passage of antidiscrimination legislation. While it&rsquo;s possible for lawmakers to plead for the passage of legislation, the context strongly suggests that it&rsquo;s the activists who pleaded for years for the passage of antidiscrimination legislation. </p>","parenttemplatename":"OSP-771-SEC","parenttemplateid":"","templateclusterid":"af358553-2b60-4afb-b29d-ca851ae54609","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959352,"updateDate":1691007959352}$SATQ$::jsonb, 1691007959352, 1691007959352),
    ($SATQ$6fac7f45$SATQ$, $SATQ$e03f7485-ceab-4c91-bc83-0288f4fc1e97$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p><em>Butterfly</em> is a 1988 painting by the Japanese artist Ay-O. Like many of Ay-O&rsquo;s paintings, <em>Butterfly</em>, which portrays a swimmer performing the butterfly stroke, attempts to make use of the entire visual light <span aria-hidden="true">______</span><span class="sr-only">blank</span> sporting rainbow-striped goggles, the rainbow-hued swimmer splashes through a wavy rainbow of water.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"7af9948b-6bfa-40cb-98d8-b69b3de92f22","content":"<p>spectrum</p>"},{"id":"a345cf36-7587-4a8b-97fa-32440a98997b","content":"<p>spectrum:</p>"},{"id":"0fbe5579-8a28-4359-8722-2db6f7594144","content":"<p>spectrum while</p>"},{"id":"974f1d21-ab29-4850-a77a-4b5c6402f949","content":"<p>spectrum, while</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["a345cf36-7587-4a8b-97fa-32440a98997b"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is the use of a colon within a sentence. In this choice, the colon correctly introduces the following description of how the painting makes use of the entire visual light spectrum by depicting a rainbow-hued swimmer.</p><p>Choice A is incorrect because it results in a run-on sentence. The main clauses ("Like&hellip;spectrum" and "sporting&hellip;water") are fused without punctuation and/or a conjunction. Choice C is incorrect because it results in a run-on sentence. The main clauses ("Like&hellip;spectrum" and "while&hellip;water") are fused without punctuation. Furthermore, the conjunction "while" fails to indicate that what follows is a description of how the painting makes use of the entire visual light spectrum. Choice D is incorrect because it results in a logically confusing sentence. The conjunction "while," which suggests that what follows is occurring at the same time as or despite what came before, fails to indicate that what follows is a description of how the painting makes use of the entire visual light spectrum.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"6fac7f45","external_id":"e03f7485-ceab-4c91-bc83-0288f4fc1e97","vaultid":null,"uId":"506bdc14-072d-4131-ae24-dba3e10123b7","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p><em>Butterfly</em> is a 1988 painting by the Japanese artist Ay-O. Like many of Ay-O&rsquo;s paintings, <em>Butterfly</em>, which portrays a swimmer performing the butterfly stroke, attempts to make use of the entire visual light <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> sporting rainbow-striped goggles, the rainbow-hued swimmer splashes through a wavy rainbow of water.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"7af9948b-6bfa-40cb-98d8-b69b3de92f22","content":"<p>spectrum</p>"},{"id":"a345cf36-7587-4a8b-97fa-32440a98997b","content":"<p>spectrum:</p>"},{"id":"0fbe5579-8a28-4359-8722-2db6f7594144","content":"<p>spectrum while</p>"},{"id":"974f1d21-ab29-4850-a77a-4b5c6402f949","content":"<p>spectrum, while</p>"}],"keys":["a345cf36-7587-4a8b-97fa-32440a98997b"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is the use of a colon within a sentence. In this choice, the colon correctly introduces the following description of how the painting makes use of the entire visual light spectrum by depicting a rainbow-hued swimmer.</p><p>Choice A is incorrect because it results in a run-on sentence. The main clauses (\"Like&hellip;spectrum\" and \"sporting&hellip;water\") are fused without punctuation and/or a conjunction. Choice C is incorrect because it results in a run-on sentence. The main clauses (\"Like&hellip;spectrum\" and \"while&hellip;water\") are fused without punctuation. Furthermore, the conjunction \"while\" fails to indicate that what follows is a description of how the painting makes use of the entire visual light spectrum. Choice D is incorrect because it results in a logically confusing sentence. The conjunction \"while,\" which suggests that what follows is occurring at the same time as or despite what came before, fails to indicate that what follows is a description of how the painting makes use of the entire visual light spectrum.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323050,"updateDate":1730147323050}$SATQ$::jsonb, 1730147323050, 1730147323050),
    ($SATQ$6fdddabf$SATQ$, $SATQ$56dd3fb5-ae99-43c6-9259-f851077a1fbb$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>The part of a compound that determines the compound&rsquo;s color is <span aria-hidden="true">______</span><span class="sr-only">blank</span> the chromophore. One example of a chromophore is hemoglobin, which gives human blood its red color.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"149ee668-4f57-4d50-8701-1734f59ecac8","content":"<p>called<span data-ssml-say-as=\"characters\">,</span></p>"},{"id":"0fbdac00-fbee-42de-8b1b-c51506711829","content":"<p>called</p>"},{"id":"b82635ab-b80e-47e9-a490-eb051843fa52","content":"<p>called<span data-ssml-say-as=\"characters\">&mdash;</span></p>"},{"id":"47b56c0f-a7e0-4596-80a8-5368b0ea5097","content":"<p>called<span data-ssml-say-as=\"characters\">;</span></p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["0fbdac00-fbee-42de-8b1b-c51506711829"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is punctuation use between a verb and its complement. No punctuation is needed between the verb &ldquo;is called&rdquo; and its complement &ldquo;the chromophore.&rdquo; The complement helps complete the idea of the verb&mdash;in this case, it explains what the part of a compound that determines the compound&rsquo;s color is called&mdash;and any punctuation between the two results in an ungrammatical sentence.</p><p>Choice A is incorrect because no punctuation is needed between the verb and its complement. Choice C is incorrect because no punctuation is needed between the verb and its complement. Choice D is incorrect because no punctuation is needed between the verb and its complement.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"6fdddabf","external_id":"56dd3fb5-ae99-43c6-9259-f851077a1fbb","vaultid":null,"uId":"52551c78-894c-4191-91c6-4a9badd9c52c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>The part of a compound that determines the compound&rsquo;s color is <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the chromophore. One example of a chromophore is hemoglobin, which gives human blood its red color.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"149ee668-4f57-4d50-8701-1734f59ecac8","content":"<p>called<span data-ssml-say-as=\"characters\">,</span></p>"},{"id":"0fbdac00-fbee-42de-8b1b-c51506711829","content":"<p>called</p>"},{"id":"b82635ab-b80e-47e9-a490-eb051843fa52","content":"<p>called<span data-ssml-say-as=\"characters\">&mdash;</span></p>"},{"id":"47b56c0f-a7e0-4596-80a8-5368b0ea5097","content":"<p>called<span data-ssml-say-as=\"characters\">;</span></p>"}],"keys":["0fbdac00-fbee-42de-8b1b-c51506711829"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is punctuation use between a verb and its complement. No punctuation is needed between the verb &ldquo;is called&rdquo; and its complement &ldquo;the chromophore.&rdquo; The complement helps complete the idea of the verb&mdash;in this case, it explains what the part of a compound that determines the compound&rsquo;s color is called&mdash;and any punctuation between the two results in an ungrammatical sentence.</p><p>Choice A is incorrect because no punctuation is needed between the verb and its complement. Choice C is incorrect because no punctuation is needed between the verb and its complement. Choice D is incorrect because no punctuation is needed between the verb and its complement.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771168,"updateDate":1776362771168}$SATQ$::jsonb, 1776362771168, 1776362771168),
    ($SATQ$6fece68e$SATQ$, $SATQ$c7948c58-730a-4e33-9b99-8b3ed2ccf4f0$SATQ$::uuid, $SATQ$82b7dbed-bbba-4cd9-a3c9-d08a2dbb489e$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>Emperor Ashoka ruled the Maurya Empire in South Asia from roughly 270 to 232 BCE. He is known for enforcing a moral code called the Law of Piety, which established the sanctity of animal <span aria-hidden="true">______</span><span class="sr-only">blank</span> the just treatment of the elderly, and the abolition of the slave trade.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"a6261e5e-86e1-45f3-8c2e-b5a3576d4381","content":"<p>life</p>"},{"id":"768ef4e5-8ff1-4563-b8b7-23bb05aae560","content":"<p>life;</p>"},{"id":"8d612724-47a2-4f32-a8b7-8aa94cb5d25f","content":"<p>life:</p>"},{"id":"bc44b834-2c60-4179-883d-74b1c41b6e5c","content":"<p>life,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["bc44b834-2c60-4179-883d-74b1c41b6e5c"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. Notice that "the sanctity of animal life" is the first item in a list of three things. We must use a comma to separate the first two items in the list, just as a comma is used to separate "the just treatment of the elderly" and "the abolition of the slave trade."</p><p>Choice A is incorrect. This choice creates a punctuation error. Notice that "the sanctity of animal life" is the first item in a list of three things. To appropriately format the list, we need punctuation to separate each item. Choice B is incorrect. This choice creates a punctuation error. Notice that "the sanctity of animal life" is the first item in a list of three things. While semicolons are sometimes used to separate list items, this list uses commas to separate the other list items, and lists must use the same punctuation throughout. Choice C is incorrect. This choice creates a punctuation error. Notice that "the sanctity of animal life" is the first item in a list of three things. While colons can be used to introduce lists, they can&rsquo;t be used to separate items within a list.</p>$SATQ$, false, 0, $SATQ$OSP-KA-BOU-E002$SATQ$, $SATQ$$SATQ$, $SATQ$4eb6903e-c99c-47b0-9e37-e8b5a4d87919$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"6fece68e","external_id":"c7948c58-730a-4e33-9b99-8b3ed2ccf4f0","vaultid":"82b7dbed-bbba-4cd9-a3c9-d08a2dbb489e","uId":"2ee32599-8f7e-49f3-a42f-2198beb511d6","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>Emperor Ashoka ruled the Maurya Empire in South Asia from roughly 270 to 232 BCE. He is known for enforcing a moral code called the Law of Piety, which established the sanctity of animal <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the just treatment of the elderly, and the abolition of the slave trade.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"a6261e5e-86e1-45f3-8c2e-b5a3576d4381","content":"<p>life</p>"},{"id":"768ef4e5-8ff1-4563-b8b7-23bb05aae560","content":"<p>life;</p>"},{"id":"8d612724-47a2-4f32-a8b7-8aa94cb5d25f","content":"<p>life:</p>"},{"id":"bc44b834-2c60-4179-883d-74b1c41b6e5c","content":"<p>life,</p>"}],"keys":["bc44b834-2c60-4179-883d-74b1c41b6e5c"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. Notice that \"the sanctity of animal life\" is the first item in a list of three things. We must use a comma to separate the first two items in the list, just as a comma is used to separate \"the just treatment of the elderly\" and \"the abolition of the slave trade.\"</p><p>Choice A is incorrect. This choice creates a punctuation error. Notice that \"the sanctity of animal life\" is the first item in a list of three things. To appropriately format the list, we need punctuation to separate each item. Choice B is incorrect. This choice creates a punctuation error. Notice that \"the sanctity of animal life\" is the first item in a list of three things. While semicolons are sometimes used to separate list items, this list uses commas to separate the other list items, and lists must use the same punctuation throughout. Choice C is incorrect. This choice creates a punctuation error. Notice that \"the sanctity of animal life\" is the first item in a list of three things. While colons can be used to introduce lists, they can&rsquo;t be used to separate items within a list.</p>","parenttemplatename":"OSP-KA-BOU-E002","parenttemplateid":"","templateclusterid":"4eb6903e-c99c-47b0-9e37-e8b5a4d87919","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959358,"updateDate":1691007959358}$SATQ$::jsonb, 1691007959358, 1691007959358),
    ($SATQ$707461d8$SATQ$, $SATQ$d4aae75d-6547-4de4-ae69-d3419e693a32$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>In <span data-ssml-say-as="date">2021</span>, Mexican biologist Martha Lydia Mac&iacute;as-Rubalcava led a review of the scientific literature related to endophytic fungi (<span data-ssml-sub-alias="i e">i.e.</span>, fungi that live inside a host <span aria-hidden="true">______</span><span class="sr-only">blank</span> researching 120 endophytic fungi&ndash;produced compounds, she found that their phytotoxicity can make them viable alternatives to chemical herbicides for controlling weeds.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"87a19b8e-ec73-40ee-aa00-c7317fcfbb78","content":"<p>plant)<span data-ssml-say-as=\"characters\">.</span> By</p>"},{"id":"d28c764c-5a35-4dc8-8ef3-9a156d80ab64","content":"<p>plant)<span data-ssml-say-as=\"characters\">,</span> by</p>"},{"id":"d623f7b8-563e-459f-8fea-401357569603","content":"<p>plant) and by</p>"},{"id":"c72dc42a-6818-4661-9b40-f81ca867e296","content":"<p>plant) by</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["87a19b8e-ec73-40ee-aa00-c7317fcfbb78"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used correctly to mark the boundary between one sentence ("In&hellip;plant") and another ("By&hellip;weeds"). The prepositional phrase beginning with "by" modifies the subject of the next sentence, "she," which refers to Mac&iacute;as-Rubalcava.</p><p>Choice B is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to join two sentences. Choice C is incorrect. Without a comma preceding it, the conjunction "and" can&rsquo;t be used in this way to join two sentences. Choice D is incorrect because it results in a run-on sentence. The two sentences are fused without punctuation and/or a conjunction.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"707461d8","external_id":"d4aae75d-6547-4de4-ae69-d3419e693a32","vaultid":null,"uId":"0caf6c29-7600-4e67-ac49-e7570bc8aca2","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>In <span data-ssml-say-as=\"date\">2021</span>, Mexican biologist Martha Lydia Mac&iacute;as-Rubalcava led a review of the scientific literature related to endophytic fungi (<span data-ssml-sub-alias=\"i e\">i.e.</span>, fungi that live inside a host <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> researching 120 endophytic fungi&ndash;produced compounds, she found that their phytotoxicity can make them viable alternatives to chemical herbicides for controlling weeds.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"87a19b8e-ec73-40ee-aa00-c7317fcfbb78","content":"<p>plant)<span data-ssml-say-as=\"characters\">.</span> By</p>"},{"id":"d28c764c-5a35-4dc8-8ef3-9a156d80ab64","content":"<p>plant)<span data-ssml-say-as=\"characters\">,</span> by</p>"},{"id":"d623f7b8-563e-459f-8fea-401357569603","content":"<p>plant) and by</p>"},{"id":"c72dc42a-6818-4661-9b40-f81ca867e296","content":"<p>plant) by</p>"}],"keys":["87a19b8e-ec73-40ee-aa00-c7317fcfbb78"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used correctly to mark the boundary between one sentence (\"In&hellip;plant\") and another (\"By&hellip;weeds\"). The prepositional phrase beginning with \"by\" modifies the subject of the next sentence, \"she,\" which refers to Mac&iacute;as-Rubalcava.</p><p>Choice B is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to join two sentences. Choice C is incorrect. Without a comma preceding it, the conjunction \"and\" can&rsquo;t be used in this way to join two sentences. Choice D is incorrect because it results in a run-on sentence. The two sentences are fused without punctuation and/or a conjunction.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061192,"updateDate":1755117061192}$SATQ$::jsonb, 1755117061192, 1755117061192),
    ($SATQ$70ced8dc$SATQ$, $SATQ$86945868-34a5-4eb0-b377-c4a626dd62d0$SATQ$::uuid, $SATQ$cb32e2a5-cd47-4b1b-b309-645ef1af86dc$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Typically, underlines, scribbles, and notes left in the margins by a former owner lower a book&rsquo;s <span aria-hidden="true">______</span><span class="sr-only">blank</span> when the former owner is a famous poet like Walt Whitman, such markings, known as marginalia, can be a gold mine to literary scholars.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"814dbfa6-cd50-4b6a-8025-7cc22f1db80b","content":"<p>value, but</p>"},{"id":"34af54bf-9c82-48ef-8394-17ee2a414d94","content":"<p>value</p>"},{"id":"37b1a9c9-40f8-4219-b8c4-deb0ac34d73f","content":"<p>value,&nbsp;</p>"},{"id":"17c1c0b2-5ec4-4237-82a3-92b9363e4cc6","content":"<p>value but</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["814dbfa6-cd50-4b6a-8025-7cc22f1db80b"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the coordination of independent clauses within a sentence. An independent clause is a phrase containing a subject and a verb that can stand on its own as a sentence. This choice uses a comma and the coordinating conjunction &ldquo;but&rdquo; to join the first independent clause (&ldquo;underlines&hellip;lower a book&rsquo;s value&rdquo;) and the second independent clause (&ldquo;such markings&hellip;can be a gold mine to scholars&rdquo;) to create a compound sentence. </p><p>Choice B is incorrect because&nbsp;it results in a run-on sentence. The two independent clauses are fused without punctuation and/or a conjunction. Choice C is incorrect because it results in a comma splice.&nbsp;A comma can&rsquo;t be used in this way to mark the boundary between two independent clauses. Choice D is incorrect because&nbsp;a comma is needed to mark the boundary between two coordinated independent clauses. </p>$SATQ$, false, 0, $SATQ$OSP-659-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$46c4ff27-170f-475e-9253-641e892fdaaa$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"70ced8dc","external_id":"86945868-34a5-4eb0-b377-c4a626dd62d0","vaultid":"cb32e2a5-cd47-4b1b-b309-645ef1af86dc","uId":"4ff6aa6d-6d5d-4cf9-9900-064791eac58f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Typically, underlines, scribbles, and notes left in the margins by a former owner lower a book&rsquo;s <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> when the former owner is a famous poet like Walt Whitman, such markings, known as marginalia, can be a gold mine to literary scholars.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"814dbfa6-cd50-4b6a-8025-7cc22f1db80b","content":"<p>value, but</p>"},{"id":"34af54bf-9c82-48ef-8394-17ee2a414d94","content":"<p>value</p>"},{"id":"37b1a9c9-40f8-4219-b8c4-deb0ac34d73f","content":"<p>value,&nbsp;</p>"},{"id":"17c1c0b2-5ec4-4237-82a3-92b9363e4cc6","content":"<p>value but</p>"}],"keys":["814dbfa6-cd50-4b6a-8025-7cc22f1db80b"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the coordination of independent clauses within a sentence. An independent clause is a phrase containing a subject and a verb that can stand on its own as a sentence. This choice uses a comma and the coordinating conjunction &ldquo;but&rdquo; to join the first independent clause (&ldquo;underlines&hellip;lower a book&rsquo;s value&rdquo;) and the second independent clause (&ldquo;such markings&hellip;can be a gold mine to scholars&rdquo;) to create a compound sentence. </p><p>Choice B is incorrect because&nbsp;it results in a run-on sentence. The two independent clauses are fused without punctuation and/or a conjunction. Choice C is incorrect because it results in a comma splice.&nbsp;A comma can&rsquo;t be used in this way to mark the boundary between two independent clauses. Choice D is incorrect because&nbsp;a comma is needed to mark the boundary between two coordinated independent clauses. </p>","parenttemplatename":"OSP-659-SEC","parenttemplateid":"","templateclusterid":"46c4ff27-170f-475e-9253-641e892fdaaa","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959341,"updateDate":1691007959341}$SATQ$::jsonb, 1691007959341, 1691007959341),
    ($SATQ$73a6603c$SATQ$, $SATQ$a168e337-aa68-4991-b999-b10743da59e1$SATQ$::uuid, $SATQ$e074c7fd-3de1-4575-8bac-9f36829452bd$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>On sunny days, dark rooftops absorb solar energy and convert it to unwanted heat, raising the surrounding air <span aria-hidden="true">______</span><span class="sr-only">blank</span> a light-colored covering to an existing dark roof, either by attaching prefabricated reflective sheets or spraying on a paint-like coating, helps combat this effect.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"64d64699-b585-4196-9211-6ec626fa487a","content":"<p>temperature; by adding</p>"},{"id":"06eb119b-7d2a-4ebd-8b5a-a9d34e636067","content":"<p>temperature, adding</p>"},{"id":"7573531a-c716-4000-a826-34107fbed022","content":"<p>temperature. Adding</p>"},{"id":"3ab37866-2fb9-47c2-99f6-8c77f5f8fad2","content":"<p>temperature by adding</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["7573531a-c716-4000-a826-34107fbed022"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used correctly to mark the boundary between the first sentence (&ldquo;On&hellip;temperature&rdquo;) and the second sentence (&ldquo;Adding&hellip;effect&rdquo;). The gerund phrase beginning with &ldquo;adding&rdquo; is the subject of the second sentence, and the verb phrase &ldquo;helps combat this effect&rdquo; describes what adding a light-colored covering can do.&nbsp;</p><p>Choice A is incorrect because a semicolon can&rsquo;t be used in this way to join the sentence &ldquo;On...temperature&rdquo; and the supplementary phrases that follow. Doing so leaves the verb phrase &ldquo;helps combat&rdquo; without a subject and thus results in a grammatically unconventional sentence. Choice B is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences. Choice D is incorrect. This choice results in a confusing and illogical sentence that suggests that adding a light-colored covering to an existing dark roof raises the temperature of the surrounding air. Furthermore, it creates ambiguity by leaving the verb phrase &ldquo;helps combat&rdquo; without a subject (so it isn&rsquo;t clear what helps combat the effect). </p>$SATQ$, false, 0, $SATQ$OSP-790-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$b32c5f9e-d59e-4ea4-ad55-43d926805d7d$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"73a6603c","external_id":"a168e337-aa68-4991-b999-b10743da59e1","vaultid":"e074c7fd-3de1-4575-8bac-9f36829452bd","uId":"4f24484d-0974-486d-b38b-c8e05b9945dd","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>On sunny days, dark rooftops absorb solar energy and convert it to unwanted heat, raising the surrounding air <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> a light-colored covering to an existing dark roof, either by attaching prefabricated reflective sheets or spraying on a paint-like coating, helps combat this effect.&nbsp;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"64d64699-b585-4196-9211-6ec626fa487a","content":"<p>temperature; by adding</p>"},{"id":"06eb119b-7d2a-4ebd-8b5a-a9d34e636067","content":"<p>temperature, adding</p>"},{"id":"7573531a-c716-4000-a826-34107fbed022","content":"<p>temperature. Adding</p>"},{"id":"3ab37866-2fb9-47c2-99f6-8c77f5f8fad2","content":"<p>temperature by adding</p>"}],"keys":["7573531a-c716-4000-a826-34107fbed022"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used correctly to mark the boundary between the first sentence (&ldquo;On&hellip;temperature&rdquo;) and the second sentence (&ldquo;Adding&hellip;effect&rdquo;). The gerund phrase beginning with &ldquo;adding&rdquo; is the subject of the second sentence, and the verb phrase &ldquo;helps combat this effect&rdquo; describes what adding a light-colored covering can do.&nbsp;</p><p>Choice A is incorrect because a semicolon can&rsquo;t be used in this way to join the sentence &ldquo;On...temperature&rdquo; and the supplementary phrases that follow. Doing so leaves the verb phrase &ldquo;helps combat&rdquo; without a subject and thus results in a grammatically unconventional sentence. Choice B is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences. Choice D is incorrect. This choice results in a confusing and illogical sentence that suggests that adding a light-colored covering to an existing dark roof raises the temperature of the surrounding air. Furthermore, it creates ambiguity by leaving the verb phrase &ldquo;helps combat&rdquo; without a subject (so it isn&rsquo;t clear what helps combat the effect). </p>","parenttemplatename":"OSP-790-SEC","parenttemplateid":"","templateclusterid":"b32c5f9e-d59e-4ea4-ad55-43d926805d7d","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959353,"updateDate":1691007959353}$SATQ$::jsonb, 1691007959353, 1691007959353),
    ($SATQ$74ce2f05$SATQ$, $SATQ$b2c3cb5c-13f8-4a31-aad8-5741ce2817de$SATQ$::uuid, $SATQ$f18fd97d-9688-4acd-8e0e-4a6a7ddfb053$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>A study led by scientist Rebecca Kirby at the University of Wisconsin&ndash;Madison found that black bears that eat human food before hibernation have increased levels of a rare carbon isotope, <span aria-hidden="true">______</span><span class="sr-only">blank</span> due to the higher <sup>13</sup>C levels in corn and cane sugar. Bears with these elevated levels were also found to have much shorter hibernation periods on average.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"49b6beda-0754-4147-979c-36447fef1d81","content":"<p>carbon-13, (<sup>13</sup>C)</p>"},{"id":"21b7de31-e262-49ba-9613-457c84d6c1e2","content":"<p>carbon-13 (<sup>13</sup>C)</p>"},{"id":"504ceafe-ab34-4fca-9bfb-0e609fd4d0fd","content":"<p>carbon-13, (<sup>13</sup>C),</p>"},{"id":"dee83dbd-f5b6-4c01-9bc2-1e2c89b5fa6b","content":"<p>carbon-13 (<sup>13</sup>C),</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["dee83dbd-f5b6-4c01-9bc2-1e2c89b5fa6b"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is the punctuation of a supplementary element within a sentence. The comma after &ldquo;(13C)&rdquo; pairs with the comma after &ldquo;isotope&rdquo; to separate the supplementary element &ldquo;carbon-13 (13C)&rdquo; from the rest of the sentence. This supplementary element defines the &ldquo;rare carbon isotope,&rdquo; and the pair of commas indicates that this element could be removed without affecting the grammatical coherence of the sentence. </p><p>Choice A is incorrect because it fails to use appropriate punctuation to separate the supplementary element &ldquo;carbon-13 (13C)&rdquo; from the rest of the sentence.&nbsp;Choice B is incorrect because it fails to use appropriate punctuation to separate the supplementary element &ldquo;carbon-13 (13C)&rdquo; from the rest of the sentence. Choice C is incorrect because it fails to use appropriate punctuation to separate the supplementary element &ldquo;carbon-13 (13C)&rdquo; from the rest of the sentence. The comma after &ldquo;carbon-13&rdquo; isn&rsquo;t necessary because the parentheses around &ldquo;13C&rdquo; already separate this element from the rest of the sentence. </p>$SATQ$, false, 0, $SATQ$OSP-611-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$8e2bb8f9-bb66-4d39-aa22-bfcb3f6e0d38$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"74ce2f05","external_id":"b2c3cb5c-13f8-4a31-aad8-5741ce2817de","vaultid":"f18fd97d-9688-4acd-8e0e-4a6a7ddfb053","uId":"0697a945-591d-4dbf-8a0d-d71ca6672b5d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>A study led by scientist Rebecca Kirby at the University of Wisconsin&ndash;Madison found that black bears that eat human food before hibernation have increased levels of a rare carbon isotope, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> due to the higher <sup>13</sup>C levels in corn and cane sugar. Bears with these elevated levels were also found to have much shorter hibernation periods on average.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"49b6beda-0754-4147-979c-36447fef1d81","content":"<p>carbon-13, (<sup>13</sup>C)</p>"},{"id":"21b7de31-e262-49ba-9613-457c84d6c1e2","content":"<p>carbon-13 (<sup>13</sup>C)</p>"},{"id":"504ceafe-ab34-4fca-9bfb-0e609fd4d0fd","content":"<p>carbon-13, (<sup>13</sup>C),</p>"},{"id":"dee83dbd-f5b6-4c01-9bc2-1e2c89b5fa6b","content":"<p>carbon-13 (<sup>13</sup>C),</p>"}],"keys":["dee83dbd-f5b6-4c01-9bc2-1e2c89b5fa6b"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is the punctuation of a supplementary element within a sentence. The comma after &ldquo;(13C)&rdquo; pairs with the comma after &ldquo;isotope&rdquo; to separate the supplementary element &ldquo;carbon-13 (13C)&rdquo; from the rest of the sentence. This supplementary element defines the &ldquo;rare carbon isotope,&rdquo; and the pair of commas indicates that this element could be removed without affecting the grammatical coherence of the sentence. </p><p>Choice A is incorrect because it fails to use appropriate punctuation to separate the supplementary element &ldquo;carbon-13 (13C)&rdquo; from the rest of the sentence.&nbsp;Choice B is incorrect because it fails to use appropriate punctuation to separate the supplementary element &ldquo;carbon-13 (13C)&rdquo; from the rest of the sentence. Choice C is incorrect because it fails to use appropriate punctuation to separate the supplementary element &ldquo;carbon-13 (13C)&rdquo; from the rest of the sentence. The comma after &ldquo;carbon-13&rdquo; isn&rsquo;t necessary because the parentheses around &ldquo;13C&rdquo; already separate this element from the rest of the sentence. </p>","parenttemplatename":"OSP-611-SEC","parenttemplateid":"","templateclusterid":"8e2bb8f9-bb66-4d39-aa22-bfcb3f6e0d38","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959339,"updateDate":1691007959339}$SATQ$::jsonb, 1691007959339, 1691007959339),
    ($SATQ$75eb5242$SATQ$, $SATQ$f537e9f7-9506-48ce-a594-e0991ce1b7db$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Many companies have simplified their products&rsquo; packaging designs in recent years, but <span aria-hidden="true">______</span><span class="sr-only">blank</span> Researcher Lan Anh Nu Ton and her colleagues designed a research study to find out.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"0926e645-4022-4eee-8e38-e769f99193a0","content":"<p>consumers actually do prefer this simpler style<span data-ssml-say-as=\"characters\">.</span></p>"},{"id":"f82bcc0c-91bc-4388-95a3-b26a99a64a02","content":"<p>do consumers actually prefer this simpler style<span data-ssml-say-as=\"characters\">?</span></p>"},{"id":"07180732-27fe-4d18-9f4b-115008536d58","content":"<p>do consumers actually prefer this simpler style<span data-ssml-say-as=\"characters\">.</span></p>"},{"id":"816d6989-9beb-4991-b2f1-4643d7bfa9b1","content":"<p>consumers actually do prefer this simpler style<span data-ssml-say-as=\"characters\">?</span></p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["f82bcc0c-91bc-4388-95a3-b26a99a64a02"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is end-of-sentence punctuation. This choice correctly uses a question mark to punctuate the interrogative clause &ldquo;do consumers actually prefer this simpler style,&rdquo; which asks a direct question at the end of the sentence. This is the question that the researchers in the next sentence were trying to investigate.</p><p>Choice A is incorrect because the context requires an interrogative clause. The declarative clause &ldquo;consumers actually do prefer this simpler style&rdquo; incorrectly indicates the consumers&rsquo; preference was already known, whereas the researchers had yet to find this out. Choice C is incorrect because a period can&rsquo;t be used in this way to punctuate an interrogative clause at the end of a sentence. Choice D is incorrect because a question mark can&rsquo;t be used in this way to punctuate a declarative clause, such as &ldquo;consumers actually do prefer this simpler style,&rdquo; at the end of a sentence.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"75eb5242","external_id":"f537e9f7-9506-48ce-a594-e0991ce1b7db","vaultid":null,"uId":"753fa996-dc6a-4d48-9417-67db8d84f0b3","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Many companies have simplified their products&rsquo; packaging designs in recent years, but <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> Researcher Lan Anh Nu Ton and her colleagues designed a research study to find out.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"0926e645-4022-4eee-8e38-e769f99193a0","content":"<p>consumers actually do prefer this simpler style<span data-ssml-say-as=\"characters\">.</span></p>"},{"id":"f82bcc0c-91bc-4388-95a3-b26a99a64a02","content":"<p>do consumers actually prefer this simpler style<span data-ssml-say-as=\"characters\">?</span></p>"},{"id":"07180732-27fe-4d18-9f4b-115008536d58","content":"<p>do consumers actually prefer this simpler style<span data-ssml-say-as=\"characters\">.</span></p>"},{"id":"816d6989-9beb-4991-b2f1-4643d7bfa9b1","content":"<p>consumers actually do prefer this simpler style<span data-ssml-say-as=\"characters\">?</span></p>"}],"keys":["f82bcc0c-91bc-4388-95a3-b26a99a64a02"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is end-of-sentence punctuation. This choice correctly uses a question mark to punctuate the interrogative clause &ldquo;do consumers actually prefer this simpler style,&rdquo; which asks a direct question at the end of the sentence. This is the question that the researchers in the next sentence were trying to investigate.</p><p>Choice A is incorrect because the context requires an interrogative clause. The declarative clause &ldquo;consumers actually do prefer this simpler style&rdquo; incorrectly indicates the consumers&rsquo; preference was already known, whereas the researchers had yet to find this out. Choice C is incorrect because a period can&rsquo;t be used in this way to punctuate an interrogative clause at the end of a sentence. Choice D is incorrect because a question mark can&rsquo;t be used in this way to punctuate a declarative clause, such as &ldquo;consumers actually do prefer this simpler style,&rdquo; at the end of a sentence.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771170,"updateDate":1776362771170}$SATQ$::jsonb, 1776362771170, 1776362771170),
    ($SATQ$75f49353$SATQ$, $SATQ$5549cd24-68fe-42a6-8f8d-7c7f385a536c$SATQ$::uuid, $SATQ$b8813dda-87db-4257-9fbb-35e1a980a9fe$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>The Progressive Era in the United States witnessed the rise of numerous Black women&rsquo;s clubs, local organizations that advocated for racial and gender equality. Among the clubs&rsquo; leaders <span aria-hidden="true">______</span><span class="sr-only">blank</span> Josephine St. Pierre Ruffin, founder of the Women&rsquo;s Era Club of Boston.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"70e26f4c-3212-415e-894b-78de1c0ed8f0","content":"<p>was</p>"},{"id":"6ece57e5-26f1-46cf-986d-4f60e77d6927","content":"<p>were</p>"},{"id":"52150bf3-25f7-46ec-9cf2-d2dc6ac52811","content":"<p>are</p>"},{"id":"f19d84da-2f96-434b-a886-a71619818116","content":"<p>have been</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["70e26f4c-3212-415e-894b-78de1c0ed8f0"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested here is subject-verb agreement. The singular verb &ldquo;was&rdquo; agrees in number with the singular subject &ldquo;Josephine St. Pierre Ruffin.&rdquo; </p><p>Choice B is incorrect because the plural verb &ldquo;were&rdquo; doesn&rsquo;t agree in number with the singular subject &ldquo;Josephine St. Pierre Ruffin.&rdquo; Choice C is incorrect because the plural verb &ldquo;are&rdquo; doesn&rsquo;t agree in number with the singular subject &ldquo;Josephine St. Pierre Ruffin.&rdquo; Choice D is incorrect because the plural verb &ldquo;have been&rdquo; doesn&rsquo;t agree in number with the singular subject &ldquo;Josephine St. Pierre Ruffin.&rdquo; </p>$SATQ$, false, 0, $SATQ$OSP-656-S